function validate([word1, word2]) {
  if (typeof word1 !== 'string' || word1.length < 1 || word1.length > 500) return 'word1 needs 1 to 500 letters.';
  if (typeof word2 !== 'string' || word2.length < 1 || word2.length > 500) return 'word2 needs 1 to 500 letters.';
  if (!/^[a-z]+$/.test(word1) || !/^[a-z]+$/.test(word2)) return 'Both words use only lowercase English letters.';
  return null;
}

