function minDistance(word1, word2) {
  // Try every subsequence of word1 that survives; keep the longest one word2 also contains.
  const isSubsequence = (small, big) => {
    let k = 0;
    for (const ch of big) if (k < small.length && small[k] === ch) k++;
    return k === small.length;
  };
  let longest = 0;
  for (let mask = 0; mask < (1 << word1.length); mask++) {
    let kept = '';
    for (let b = 0; b < word1.length; b++) if (mask & (1 << b)) kept += word1[b];
    if (kept.length > longest && isSubsequence(kept, word2)) longest = kept.length;
  }
  return word1.length + word2.length - 2 * longest;
}

