function generate(rand, size) {
  const word = (len, letters) => {
    let s = '';
    for (let i = 0; i < len; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
    return s;
  };
  if (size === 'large') {
    const letters = 2 + Math.floor(rand() * 25);
    return [word(500, letters), word(400 + Math.floor(rand() * 101), letters)];
  }
  const letters = 1 + Math.floor(rand() * 4);
  return [word(1 + Math.floor(rand() * 8), letters), word(1 + Math.floor(rand() * 8), letters)];
}
